{
  "type": "object",
  "properties": {
    "items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "sku": {
            "type": "string",
            "description": "Product SKU or article number"
          },
          "name": {
            "type": "string",
            "description": "Product name or description"
          },
          "qty": {
            "type": "integer",
            "description": "Quantity (must be >= 0)"
          },
          "supplier": {
            "type": [
              "string",
              "null"
            ],
            "description": "Supplier name or null if not found"
          }
        },
        "required": [
          "sku",
          "name",
          "qty"
        ]
      }
    },
    "metadata": {
      "type": [
        "object",
        "null"
      ],
      "properties": {
        "project_name": {
          "type": "string"
        },
        "client": {
          "type": "string"
        }
      }
    }
  },
  "required": [
    "items"
  ]
}
